package io.nebulaflow.rag;
import java.util.*;
public class RagChunker { public List<String> split(String text,int size,int overlap){if(text==null||text.isBlank())return List.of();if(size<64||overlap<0||overlap>=size)throw new IllegalArgumentException("invalid chunk size or overlap");List<String> out=new ArrayList<>();int start=0;while(start<text.length()){int end=Math.min(text.length(),start+size);if(end<text.length()){int b=end;while(b>start+size/2&&!Character.isWhitespace(text.charAt(b-1)))b--;if(b>start+size/2)end=b;}String chunk=text.substring(start,end).trim();if(!chunk.isEmpty())out.add(chunk);if(end==text.length())break;int next=Math.max(start+1,end-overlap);while(next<text.length()&&Character.isWhitespace(text.charAt(next)))next++;start=next;}return List.copyOf(out);} }